 'template_seed_exact',(SELECT jsonb_build_object('versions',(SELECT jsonb_agg(to_jsonb(v) ORDER BY id) FROM public.case_flow_versions v),'stages',(SELECT jsonb_agg(to_jsonb(s) ORDER BY template_id,ordinal) FROM public.case_flow_stages s)))='{"stages":[{"ordinal":1,"title_en":"Prepare and draft claim","title_th":"เตรียมและร่างคำฟ้อง","stage_key":"prepare_claim","template_id":"civil_ordinary_plaintiff_v1"},{"ordinal":2,"title_en":"File claim","title_th":"ยื่นฟ้อง","stage_key":"file_claim","template_id":"civil_ordinary_plaintiff_v1"},{"ordinal":3,"title_en":"Claim accepted / first hearing scheduled","title_th":"ศาลรับฟ้อง / ได้วันนัดแรก","stage_key":"accepted","template_id":"civil_ordinary_plaintiff_v1"},{"ordinal":4,"title_en":"Await and manage service on defendants","title_th":"รอและจัดการการส่งหมายจำเลย","stage_key":"service","template_id":"civil_ordinary_plaintiff_v1"},{"ordinal":5,"title_en":"Await defence / first hearing","title_th":"รอคำให้การ / นัดแรก","stage_key":"defence","template_id":"civil_ordinary_plaintiff_v1"},{"ordinal":6,"title_en":"Settlement of issues / mediation","title_th":"ชี้สองสถาน / ไกล่เกลี่ย","stage_key":"issues_mediation","template_id":"civil_ordinary_plaintiff_v1"},{"ordinal":7,"title_en":"Prepare evidence hearing","title_th":"เตรียมสืบพยาน","stage_key":"prepare_evidence","template_id":"civil_ordinary_plaintiff_v1"},{"ordinal":8,"title_en":"Evidence hearing","title_th":"สืบพยาน","stage_key":"evidence","template_id":"civil_ordinary_plaintiff_v1"},{"ordinal":9,"title_en":"Await judgment","title_th":"รอฟังคำพิพากษา","stage_key":"await_judgment","template_id":"civil_ordinary_plaintiff_v1"},{"ordinal":10,"title_en":"First-instance judgment / report","title_th":"คำพิพากษาศาลชั้นต้น / รายงานผล","stage_key":"judgment","template_id":"civil_ordinary_plaintiff_v1"},{"ordinal":11,"title_en":"Post-judgment analysis and report","title_th":"หลังคำพิพากษา / วิเคราะห์และรายงาน","stage_key":"post_judgment","template_id":"civil_ordinary_plaintiff_v1"},{"ord